using Microsoft.EntityFrameworkCore;
namespace Spilton.Api.Mocks;
public static class MockModel
{
 public static void Configure(ModelBuilder m){
  var q=m.Entity<Question>();q.HasOne(q=>q.User).WithMany().HasForeignKey(q=>q.UserId).OnDelete(DeleteBehavior.Restrict);q.HasOne(q=>q.Space).WithMany().HasForeignKey(q=>q.SpaceId).OnDelete(DeleteBehavior.Restrict);q.HasOne(q=>q.Topic).WithMany().HasForeignKey(q=>q.TopicId).OnDelete(DeleteBehavior.Restrict);q.HasOne(q=>q.SourceResource).WithMany().HasForeignKey(q=>q.SourceResourceId).OnDelete(DeleteBehavior.SetNull);q.Property(q=>q.SourceMetadataJson).HasColumnType("jsonb");q.HasIndex(q=>new{q.UserId,q.SpaceId,q.TopicId});q.ToTable(t=>t.HasCheckConstraint("CK_Question_Answer","\"CorrectOptionIndex\" BETWEEN 0 AND 3"));
  var options=m.Entity<QuestionOption>();options.HasOne(o=>o.Question).WithMany(q=>q.Options).HasForeignKey(o=>o.QuestionId).OnDelete(DeleteBehavior.Cascade);options.HasIndex(o=>new{o.QuestionId,o.Index}).IsUnique();options.ToTable(t=>t.HasCheckConstraint("CK_Option_Index","\"Index\" BETWEEN 0 AND 3"));
  var tests=m.Entity<MockTest>();tests.HasOne(t=>t.User).WithMany().HasForeignKey(t=>t.UserId).OnDelete(DeleteBehavior.Restrict);tests.HasOne(t=>t.Space).WithMany().HasForeignKey(t=>t.SpaceId).OnDelete(DeleteBehavior.Restrict);tests.HasOne(t=>t.ExamStage).WithMany().HasForeignKey(t=>t.ExamStageId).OnDelete(DeleteBehavior.Restrict);
  var sections=m.Entity<MockSection>();sections.HasOne(s=>s.MockTest).WithMany(t=>t.Sections).HasForeignKey(s=>s.MockTestId).OnDelete(DeleteBehavior.Cascade);sections.HasOne(s=>s.Subject).WithMany().HasForeignKey(s=>s.SubjectId).OnDelete(DeleteBehavior.Restrict);sections.Property(s=>s.MarksCorrect).HasPrecision(8,2);sections.Property(s=>s.NegativeMarks).HasPrecision(8,2);sections.HasIndex(s=>new{s.MockTestId,s.Position}).IsUnique();
  var links=m.Entity<MockTestQuestion>();links.HasKey(l=>new{l.MockTestId,l.QuestionId});links.HasOne(l=>l.MockTest).WithMany(t=>t.Questions).HasForeignKey(l=>l.MockTestId).OnDelete(DeleteBehavior.Cascade);links.HasOne(l=>l.Question).WithMany().HasForeignKey(l=>l.QuestionId).OnDelete(DeleteBehavior.Restrict);links.HasOne(l=>l.MockSection).WithMany().HasForeignKey(l=>l.MockSectionId).OnDelete(DeleteBehavior.Restrict);links.HasIndex(l=>new{l.MockTestId,l.Position}).IsUnique();
  var a=m.Entity<MockAttempt>();a.HasOne(a=>a.User).WithMany().HasForeignKey(a=>a.UserId).OnDelete(DeleteBehavior.Restrict);a.HasOne(a=>a.Space).WithMany().HasForeignKey(a=>a.SpaceId).OnDelete(DeleteBehavior.Restrict);a.HasOne(a=>a.MockTest).WithMany().HasForeignKey(a=>a.MockTestId).OnDelete(DeleteBehavior.Restrict);a.HasOne(a=>a.UserExamProfile).WithMany().HasForeignKey(a=>a.UserExamProfileId).OnDelete(DeleteBehavior.Restrict);a.HasIndex(a=>new{a.UserId,a.StartKey}).IsUnique();a.HasIndex(a=>new{a.Status,a.ExpiresAt});a.HasIndex(a=>new{a.UserId,a.SpaceId,a.StartedAt});
  foreach(var name in new[]{"RawScore","NegativeMarks","FinalScore","AccuracyPercent"})a.Property(name).HasPrecision(10,2);
  var answers=m.Entity<AttemptAnswer>();answers.HasKey(a=>new{a.MockAttemptId,a.QuestionId});answers.HasOne(a=>a.MockAttempt).WithMany(a=>a.Answers).HasForeignKey(a=>a.MockAttemptId).OnDelete(DeleteBehavior.Cascade);answers.HasOne(a=>a.Question).WithMany().HasForeignKey(a=>a.QuestionId).OnDelete(DeleteBehavior.Restrict);answers.HasOne(a=>a.Option).WithMany().HasForeignKey(a=>a.OptionId).OnDelete(DeleteBehavior.Restrict);answers.Property(a=>a.MarksCorrect).HasPrecision(8,2);answers.Property(a=>a.NegativeMarks).HasPrecision(8,2);answers.Property(a=>a.Score).HasPrecision(8,2);
  MockSeed.Configure(m);
 }
